                  <path d={v.pathJuros} fill="none" stroke="#F59E0B" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" pathLength="1" strokeDasharray="1" style={{ "animation": "drawLine 1.1s cubic-bezier(.16,1,.3,1) .15s both" }}></path>
